/* @ts-ignore */
import * as libsignal from 'libsignal'
import { LRUCache } from 'lru-cache'
import type { LIDMapping, SignalAuthState, SignalKeyStoreWithTransaction } from '../Types'
import type { SignalRepositoryWithLIDStore } from '../Types/Signal'
import { generateSignalPubKey } from '../Utils'
import type { ILogger } from '../Utils/logger'
import {
  isHostedLidUser,
  isHostedPnUser,
  isLidUser,
  isPnUser,
  jidDecode,
  transferDevice,
  WAJIDDomains
} from '../WABinary'
import { GroupCipher, GroupSessionBuilder, SenderKeyDistributionMessage } from './Group'
import type { SenderKeyStore } from './Group/group_cipher'
import { SenderKeyName } from './Group/sender-key-name'
import { SenderKeyRecord } from './Group/sender-key-record'
import { getKeyBackupStore } from './key-backup-store'
import { LIDMappingStore } from './lid-mapping'

export function makeLibSignalRepository(
	auth: SignalAuthState,
	logger: ILogger,
	pnToLIDFunc?: (jids: string[]) => Promise<LIDMapping[] | undefined>
): SignalRepositoryWithLIDStore {
	const lidMapping = new LIDMappingStore(auth.keys as SignalKeyStoreWithTransaction, logger, pnToLIDFunc)
	const storage = signalStorage(auth, lidMapping)

	const parsedKeys = auth.keys as SignalKeyStoreWithTransaction
	const migratedSessionCache = new LRUCache<string, true>({
		ttl: 7 * 24 * 60 * 60 * 1000, // 7 days - para sessões que já foram migradas
		ttlAutopurge: true,
		updateAgeOnGet: true
	})
	
	// 🚀 THROTTLE CACHE: Para evitar chamadas repetidas de migrateSession
	// TTL curto de 30 segundos - apenas para evitar spam, não bloqueia permanentemente
	const migrationThrottleCache = new LRUCache<string, true>({
		max: 5000,
		ttl: 30 * 1000, // 30 segundos - tempo suficiente para evitar spam
		ttlAutopurge: true
	})

	// 🔐 SISTEMA DE BACKUP PERSISTENTE DE CHAVES (SQLite)
	// Armazena backups de sessões e sender keys em dados/DB/chaves.db
	const keyBackupStore = getKeyBackupStore()
	
	// Inicializar o backup store de forma assíncrona
	keyBackupStore.init().then(initialized => {
		if (initialized) {
			const stats = keyBackupStore.getStats()
			logger.info({ 
				dbPath: stats.dbPath, 
				sessions: stats.sessions, 
				senderKeys: stats.senderKeys 
			}, '🔐 Key backup store initialized')
		}
	}).catch(() => {
		// Silently ignore initialization errors
	})

	// Função para fazer backup de uma sessão antes de deletar
	async function backupSession(sessionId: string): Promise<void> {
		try {
			const { [sessionId]: sessionData } = await parsedKeys.get('session', [sessionId])
			if (sessionData) {
				await keyBackupStore.backupSession(sessionId, sessionData)
				logger.debug({ sessionId }, 'Session backed up to SQLite')
			}
		} catch (error) {
			// Silently ignore backup errors
		}
	}

	// Função para tentar recuperar uma sessão do backup
	async function tryRestoreSession(sessionId: string): Promise<boolean> {
		try {
			const backup = await keyBackupStore.getSessionBackup(sessionId)
			if (backup) {
				await auth.keys.set({ session: { [sessionId]: backup } })
				logger.info({ sessionId }, '✅ Session restored from SQLite backup!')
				return true
			}
		} catch (error) {
			logger.warn({ sessionId, error }, 'Failed to restore session from backup')
		}
		return false
	}

	// Função para fazer backup de uma sender key antes de deletar
	async function backupSenderKey(keyId: string): Promise<void> {
		try {
			const { [keyId]: keyData } = await auth.keys.get('sender-key', [keyId])
			if (keyData) {
				await keyBackupStore.backupSenderKey(keyId, keyData)
				logger.debug({ keyId: keyId.substring(0, 30) }, 'Sender key backed up to SQLite')
			}
		} catch (error) {
			// Silently ignore backup errors
		}
	}

	// Função para tentar recuperar uma sender key do backup
	async function tryRestoreSenderKey(keyId: string): Promise<boolean> {
		try {
			logger.info({ keyId: keyId.substring(0, 40) }, '🔍 Attempting to restore sender key from SQLite...')
			const backup = await keyBackupStore.getSenderKeyBackup(keyId)
			
			if (backup) {
				logger.info({ 
					keyId: keyId.substring(0, 40),
					backupType: typeof backup,
					backupSize: typeof backup === 'object' ? Object.keys(backup).length : 0
				}, '📦 Found backup in SQLite!')
				
				// O backup é um objeto serializado - converter de volta para Uint8Array
				let dataToRestore = backup
				
				// Se é um objeto com índices numéricos (serializado de Uint8Array), converter
				if (typeof backup === 'object' && !Buffer.isBuffer(backup) && !(backup instanceof Uint8Array)) {
					// Verificar se tem índices numéricos (formato JSON.stringify de Uint8Array)
					const keys = Object.keys(backup)
					if (keys.length > 0 && !isNaN(Number(keys[0]))) {
						const arr = new Uint8Array(keys.length)
						for (let i = 0; i < keys.length; i++) {
							arr[i] = backup[i]
						}
						dataToRestore = arr
						logger.info({ keyId: keyId.substring(0, 40), size: arr.length }, 
							'🔄 Converted backup to Uint8Array')
					}
				}
				
				await auth.keys.set({ 'sender-key': { [keyId]: dataToRestore } })
				logger.info({ keyId: keyId.substring(0, 30) }, '✅ Sender key restored from SQLite backup!')
				return true
			} else {
				logger.info({ keyId: keyId.substring(0, 40) }, '📭 No backup found in SQLite')
			}
		} catch (error) {
			logger.warn({ keyId: keyId.substring(0, 30), error: (error as Error).message }, 
				'Failed to restore sender key from backup')
		}
		return false
	}

	// Função para deletar backup de sessão inútil
	async function deleteSessionBackup(sessionId: string): Promise<void> {
		try {
			await keyBackupStore.deleteSessionBackup(sessionId)
		} catch (error) {
			// Silently ignore
		}
	}

	// Função para deletar backup de sender key inútil
	async function deleteSenderKeyBackup(keyId: string): Promise<void> {
		try {
			await keyBackupStore.deleteSenderKeyBackup(keyId)
		} catch (error) {
			// Silently ignore
		}
	}

	/**
	 * 🔐 SISTEMA DE MENSAGENS PENDENTES
	 * Armazena mensagens que falharam por keyId desconhecido
	 * para tentar descriptografar quando a SKDM chegar
	 * 
	 * 🚀 OTIMIZADO para 20+ grupos × 1024 membros:
	 * - TTL reduzido: 15s (era 30s) - celular offline = sem PDO
	 * - Cleanup mais frequente: 5s (era 10s)
	 * - Limite de entradas processadas por cleanup: 50
	 */
	const pendingGroupMessages = new Map<string, Array<{
		msg: Uint8Array
		timestamp: number
		attempts: number
	}>>()
	const PENDING_MSG_TTL = 15000 // 15 segundos (reduzido de 30s)
	const PENDING_MSG_MAX_ATTEMPTS = 2 // Reduzido de 3 para 2
	const CLEANUP_BATCH_SIZE = 50 // Máximo de entradas por cleanup

	// Limpar mensagens pendentes antigas periodicamente
	setInterval(() => {
		const now = Date.now()
		let processedCount = 0
		
		for (const [key, messages] of pendingGroupMessages) {
			if (processedCount >= CLEANUP_BATCH_SIZE) break
			
			const filtered = messages.filter(m => now - m.timestamp < PENDING_MSG_TTL)
			if (filtered.length === 0) {
				pendingGroupMessages.delete(key)
			} else {
				pendingGroupMessages.set(key, filtered)
			}
			processedCount++
		}
	}, 5000) // Reduzido de 10s para 5s

	const repository: SignalRepositoryWithLIDStore = {
		decryptGroupMessage({ group, authorJid, msg }) {
			const senderName = jidToSignalSenderKeyName(group, authorJid)
			const senderKeyId = senderName.toString()
			const cipher = new GroupCipher(storage, senderName)

			// Use transaction to ensure atomicity
			return parsedKeys.transaction(async () => {
				// 🚀 PRE-LOAD: Verificar se sender key existe ANTES de tentar decriptar
				// Isso elimina o delay quando temos backup disponível
				const { [senderKeyId]: existingKey } = await auth.keys.get('sender-key', [senderKeyId])
				
				// Log de trace (só aparece em modo debug para evitar spam)
				logger.trace({ 
					group, 
					authorJid, 
					hasKey: !!existingKey,
					senderKeyId: senderKeyId.substring(0, 50)
				}, 'Checking sender key for group message')
				
				if (!existingKey) {
					// Sender key não existe - tentar restaurar do backup SQLite ANTES de falhar
					logger.debug({ group, authorJid, senderKeyId: senderKeyId.substring(0, 50) }, 
						'🔍 No sender key found, checking SQLite backup...')
					const restored = await tryRestoreSenderKey(senderKeyId)
					if (restored) {
						logger.info({ group, authorJid }, 
							'🚀 PRE-LOADED sender key from SQLite backup!')
					} else {
						logger.debug({ group, authorJid }, 
							'❌ No backup found in SQLite - will need SKDM or PDO')
					}
				}

				try {
					// Tentar descriptografar
					return await cipher.decrypt(msg)
				} catch (decryptError: any) {
				const errorMsg = decryptError?.message || ''
				
				// 🔧 FIX 1: Contador antigo = sender key DESSINCRONIZADA após reinício
				// Isso acontece quando:
				// 1. Bot reinicia e restaura sender key do backup SQLite
				// 2. O backup tem contador antigo (ex: 286)
				// 3. Mensagens offline chegam com contador mais novo (ex: 323)
				// 4. Ou vice-versa
				// Solução: invalidar a chave e deixar retry solicitar nova SKDM
				if (errorMsg.includes('old counter') || errorMsg.includes('Received message with old counter')) {
					logger.warn({ group, authorJid, senderKeyId: senderKeyId.substring(0, 50), error: errorMsg }, 
						'⚠️ Sender key desync detected - invalidating stale key and requesting new SKDM')
					
					// Invalidar sender key dessincronizada do cache
					await auth.keys.set({ 'sender-key': { [senderKeyId]: null } })
					// Deletar backup obsoleto para evitar restaurar lixo na próxima vez
					await deleteSenderKeyBackup(senderKeyId)
					
					// NÃO armazenar como pendente - deixar retry normal solicitar nova SKDM
					// Lançar erro para que o retry mechanism funcione
					throw decryptError
				}
				
				// 🔧 FIX 2: Mensagem duplicada = já processada ANTES do reinício
				// Isso acontece quando o bot caiu enquanto processava uma mensagem
				// e ao reiniciar, tenta processar a mesma mensagem novamente.
				// Solução: lançar erro especial que será capturado e tratado como CIPHERTEXT
				// (NÃO retornar Buffer vazio - isso causa erro no unpadRandomMax16)
				if (errorMsg.includes('DuplicatedMessage')) {
					logger.debug({ group, authorJid }, 
						'🔄 Duplicate message (already processed before restart), marking as processed')
					// Lançar erro que será capturado no decode-wa-message.ts
					// A mensagem será marcada como CIPHERTEXT mas nenhum retry será enviado
					// porque não é erro de sessão (não está na lista sessionRecordErrors)
					throw new Error('Duplicate message - already processed before restart')
				}
				
				// 🔄 IGUAL À BAILEYS OFICIAL: NÃO invalidar a sender-key para outros erros!
				// A baileys oficial apenas envia retry receipt e espera.
				// Invalidar a sender-key causa problemas porque:
				// 1. A sender key pode ainda ser válida (o participante não regenerou)
				// 2. Forçar PDO quando o celular está offline causa perda de mensagens
				// 
				// O mecanismo correto é:
				// 1. Enviar retry receipt
				// 2. O remetente reenvia a mensagem (pode incluir SKDM)
				// 3. Se falhar várias vezes, o PDO é usado como fallback
				
				if (errorMsg.includes('No session found to decrypt message')) {
					logger.debug({ group, authorJid, senderKeyId: senderKeyId.substring(0, 50) }, 
						'⏳ Sender key decrypt failed - retry receipt will be sent')
					
					// Armazenar mensagem para tentar quando SKDM chegar
					const pending = pendingGroupMessages.get(senderKeyId) || []
					const msgHash = Buffer.from(msg).toString('base64').slice(0, 50)
					const alreadyPending = pending.some(p => 
						Buffer.from(p.msg).toString('base64').slice(0, 50) === msgHash
					)
					
					if (!alreadyPending && pending.length < 5) {
						pending.push({ msg: new Uint8Array(msg), timestamp: Date.now(), attempts: 0 })
						pendingGroupMessages.set(senderKeyId, pending)
						logger.debug({ group, authorJid, pendingCount: pending.length }, 
							'📬 Mensagem armazenada aguardando SKDM')
					}
				}
				
				throw decryptError
			}
			}, group)
		},
		async processSenderKeyDistributionMessage({ item, authorJid }) {
			// 🔄 SIMPLIFICADO: Igual à Baileys oficial para evitar problemas
			const builder = new GroupSessionBuilder(storage)
			if (!item.groupId) {
				throw new Error('Group ID is required for sender key distribution message')
			}

			const senderName = jidToSignalSenderKeyName(item.groupId, authorJid)
			const senderNameStr = senderName.toString()

			// Criar SenderKeyDistributionMessage diretamente como na oficial
			const senderMsg = new SenderKeyDistributionMessage(
				null,
				null,
				null,
				null,
				item.axolotlSenderKeyDistributionMessage
			)

			// Verificar se sender key existe FORA da transação (como na oficial)
			const { [senderNameStr]: senderKey } = await auth.keys.get('sender-key', [senderNameStr])
			if (!senderKey) {
				await storage.storeSenderKey(senderName, new SenderKeyRecord())
			}

			return parsedKeys.transaction(async () => {
				// Verificar novamente dentro da transação (como na oficial)
				const { [senderNameStr]: senderKeyInTx } = await auth.keys.get('sender-key', [senderNameStr])
				if (!senderKeyInTx) {
					await storage.storeSenderKey(senderName, new SenderKeyRecord())
				}

				await builder.process(senderName, senderMsg)
				
				logger?.info({ authorJid, groupId: item.groupId }, 
					'🔐 SKDM processada com sucesso!')
				
				// Processar mensagens pendentes se houver
				const pendingMsgs = pendingGroupMessages.get(senderNameStr)
				if (pendingMsgs && pendingMsgs.length > 0) {
					logger?.info({ authorJid, groupId: item.groupId, pendingCount: pendingMsgs.length }, 
						'📬 Processando mensagens pendentes após receber SKDM!')
					
					const cipher = new GroupCipher(storage, senderName)
					
					for (const pending of pendingMsgs) {
						pending.attempts++
						if (pending.attempts <= PENDING_MSG_MAX_ATTEMPTS) {
							try {
								await cipher.decrypt(pending.msg)
								logger?.info({ authorJid, groupId: item.groupId }, 
									'✅ Mensagem pendente descriptografada!')
							} catch {
								// Ignorar erros
							}
						}
					}
					
					pendingGroupMessages.delete(senderNameStr)
				}
			}, item.groupId)
		},
		async decryptMessage({ jid, type, ciphertext }) {
			const addr = jidToSignalProtocolAddress(jid)
			const sessionId = addr.toString()
			const session = new libsignal.SessionCipher(storage, addr)

			async function doDecrypt(isRetryAfterRestore = false): Promise<Buffer> {
				let result: Buffer
				try {
					switch (type) {
						case 'pkmsg':
							result = await session.decryptPreKeyWhisperMessage(ciphertext)
							break
						case 'msg':
							result = await session.decryptWhisperMessage(ciphertext)
							break
					}
				} catch (decryptError: any) {
					const errorMessage = decryptError?.message || decryptError?.toString() || ''
					
					// 🔧 FIX: Mensagem duplicada em chat direto (já processada antes do reinício)
					// Isso acontece quando o bot caiu enquanto processava uma mensagem 1:1
					// e ao reiniciar, tenta processar a mesma mensagem novamente.
					if (errorMessage.includes('DuplicatedMessage')) {
						logger.debug({ jid }, 
							'🔄 Duplicate direct message (already processed before restart), marking as processed')
						// Lançar erro que será capturado no decode-wa-message.ts
						// A mensagem será marcada como CIPHERTEXT mas nenhum retry será enviado
						throw new Error('Duplicate message - already processed before restart')
					}
					
					// Erro de counter de mensagens - chave já usada ou dessincronizada
					if (errorMessage.includes('Key used already') || 
						errorMessage.includes('never filled') ||
						errorMessage.includes('MessageCounterError')) {
						
						// 🔐 Fazer backup antes de deletar
						await backupSession(sessionId)
						
						logger.warn({ jid }, 'MessageCounterError detected, session backed up and deleted')
						await auth.keys.set({ session: { [sessionId]: null } })
						throw new Error(`MessageCounterError: Session deleted for ${jid}, retry needed`)
					}
					
					// Erro de sessão não encontrada - tentar restaurar do backup
					if (errorMessage.includes('No sessions') || errorMessage.includes('No session')) {
						// 🔐 Tentar restaurar do backup se ainda não tentou
						if (!isRetryAfterRestore) {
							const restored = await tryRestoreSession(sessionId)
							if (restored) {
								logger.info({ jid }, 'Session restored from backup, retrying decrypt...')
								// Criar novo cipher com a sessão restaurada
								const newSession = new libsignal.SessionCipher(storage, addr)
								try {
									switch (type) {
										case 'pkmsg':
											return await newSession.decryptPreKeyWhisperMessage(ciphertext)
										case 'msg':
											return await newSession.decryptWhisperMessage(ciphertext)
									}
								} catch (retryError) {
									// Se falhar mesmo após restaurar, deletar backup e deixar o retry normal
									logger.debug({ jid }, 'Backup was not usable, waiting for retry...')
									await deleteSessionBackup(sessionId)
								}
							} else {
								// Não tem backup, apenas deixar o sistema de retry carregar a sessão
								logger.debug({ jid }, 'No backup available, waiting for session sync...')
							}
						}
						// Deixar o erro propagar para o sistema de retry solicitar reenvio
						throw new Error(`SessionError: No sessions available for ${jid}`)
					}
					
					throw decryptError
				}

				return result!
			}

			// If it's not a sync message, we need to ensure atomicity
			// For regular messages, we use a transaction to ensure atomicity
			return parsedKeys.transaction(async () => {
				return await doDecrypt()
			}, jid)
		},

		async encryptMessage({ jid, data }) {
			const addr = jidToSignalProtocolAddress(jid)
			const cipher = new libsignal.SessionCipher(storage, addr)

			// Use transaction to ensure atomicity
			return parsedKeys.transaction(async () => {
				const { type: sigType, body } = await cipher.encrypt(data)
				const type = sigType === 3 ? 'pkmsg' : 'msg'
				return { type, ciphertext: Buffer.from(body, 'binary') }
			}, jid)
		},

		async encryptGroupMessage({ group, meId, data }) {
			const senderName = jidToSignalSenderKeyName(group, meId)
			const builder = new GroupSessionBuilder(storage)

			return parsedKeys.transaction(async () => {
				// builder.create() cria e salva a sender key automaticamente
				const senderKeyDistributionMessage = await builder.create(senderName)
				const session = new GroupCipher(storage, senderName)
				const ciphertext = await session.encrypt(data)

				return {
					ciphertext,
					senderKeyDistributionMessage: senderKeyDistributionMessage.serialize()
				}
			}, group)
		},

		async injectE2ESession({ jid, session }) {
			logger.trace({ jid }, 'injecting E2EE session')
			const addr = jidToSignalProtocolAddress(jid)
			const cipher = new libsignal.SessionBuilder(storage, addr)
			
			return parsedKeys.transaction(async () => {
				try {
					await cipher.initOutgoing(session)
				} catch (error) {
					// Se falhar, tentar limpar sessão anterior e reinjetar
					const errorMsg = (error as Error).message || ''
					if (errorMsg.includes('session') || errorMsg.includes('identity')) {
						await auth.keys.set({ session: { [addr.toString()]: null } })
						await cipher.initOutgoing(session)
					} else {
						throw error
					}
				}
			}, jid)
		},
		jidToSignalProtocolAddress(jid) {
			return jidToSignalProtocolAddress(jid).toString()
		},

		// Optimized direct access to LID mapping store
		lidMapping,

		async validateSession(jid: string) {
			try {
				const addr = jidToSignalProtocolAddress(jid)
				const session = await storage.loadSession(addr.toString())

				if (!session) {
					return { exists: false, reason: 'no session' }
				}

				if (!session.haveOpenSession()) {
					return { exists: false, reason: 'no open session' }
				}

				return { exists: true }
			} catch (error) {
				return { exists: false, reason: 'validation error' }
			}
		},

		async deleteSession(jids: string[]) {
			if (!jids.length) return

			// Convert JIDs to signal addresses and prepare for bulk deletion
			const sessionUpdates: { [key: string]: null } = {}
			jids.forEach(jid => {
				const addr = jidToSignalProtocolAddress(jid)
				sessionUpdates[addr.toString()] = null
			})

			// Single transaction for all deletions
			return parsedKeys.transaction(async () => {
				await auth.keys.set({ session: sessionUpdates })
			}, `delete-${jids.length}-sessions`)
		},

		/**
		 * Verifica se tem a sender key de um participante em um grupo
		 */
		async hasSenderKey(groupJid: string, participantJid: string): Promise<boolean> {
			try {
				const senderName = jidToSignalSenderKeyName(groupJid, participantJid)
				const keyId = senderName.toString()
				const { [keyId]: key } = await auth.keys.get('sender-key', [keyId])
				
				if (!key) return false
				
				const record = SenderKeyRecord.deserialize(key)
				return !record.isEmpty()
			} catch {
				return false
			}
		},

		/**
		 * Verifica quais participantes de um grupo NÃO têm sender key
		 * Útil para diagnóstico
		 */
		async getMissingSenderKeys(groupJid: string, participantJids: string[]): Promise<string[]> {
			const missing: string[] = []
			
			for (const participant of participantJids) {
				const has = await repository.hasSenderKey(groupJid, participant)
				if (!has) {
					missing.push(participant)
				}
			}
			
			return missing
		},

		/**
		 * Remove a sender key de um participante (força re-sincronização)
		 */
		async resetSenderKey(groupJid: string, participantJid: string): Promise<void> {
			const senderName = jidToSignalSenderKeyName(groupJid, participantJid)
			const keyId = senderName.toString()
			await auth.keys.set({ 'sender-key': { [keyId]: null } })
			
			// 🔐 IMPORTANTE: Deletar backup SQLite também!
			// Quando participante sai, o backup fica obsoleto (novo keyId ao voltar)
			await deleteSenderKeyBackup(keyId)
			logger.debug({ groupJid, participantJid, keyId: keyId.substring(0, 30) }, 
				'🗑️ Deleted stale sender key backup - participant left')
		},

		/**
		 * Remove todas as sender keys de um grupo (força re-sincronização completa)
		 */
		async resetGroupSenderKeys(groupJid: string, participantJids: string[]): Promise<void> {
			const updates: { [key: string]: null } = {}
			
			for (const participant of participantJids) {
				const senderName = jidToSignalSenderKeyName(groupJid, participant)
				updates[senderName.toString()] = null
			}
			
			await auth.keys.set({ 'sender-key': updates })
		},

		async migrateSession(
			fromJid: string,
			toJid: string
		): Promise<{ migrated: number; skipped: number; total: number }> {
			// TODO: use usync to handle this entire mess
			if (!fromJid || (!isLidUser(toJid) && !isHostedLidUser(toJid))) return { migrated: 0, skipped: 0, total: 0 }

			// Only support PN to LID migration
			if (!isPnUser(fromJid) && !isHostedPnUser(fromJid)) {
				return { migrated: 0, skipped: 0, total: 1 }
			}

			const { user } = jidDecode(fromJid)!
			
			// 🚀 THROTTLE: Evitar chamadas repetidas para o mesmo usuário
			// Isso previne o congelamento em grupos grandes onde múltiplas mensagens
			// do mesmo usuário chegam em sequência rápida
			const throttleKey = `migrate:${user}`
			if (migrationThrottleCache.has(throttleKey)) {
				// Já migramos este usuário recentemente (últimos 30s), pular silenciosamente
				return { migrated: 0, skipped: 1, total: 1 }
			}
			// Marcar como processado por 30 segundos (evita spam de migrações)
			migrationThrottleCache.set(throttleKey, true)

			// Log reduzido para trace (não aparece por padrão, apenas com debug ativado)
			logger.trace({ fromJid }, 'bulk device migration - loading all user devices')

			// Get user's device list from storage
			const { [user]: userDevices } = await parsedKeys.get('device-list', [user])
			if (!userDevices) {
				return { migrated: 0, skipped: 0, total: 0 }
			}

			const { device: fromDevice } = jidDecode(fromJid)!
			const fromDeviceStr = fromDevice?.toString() || '0'
			if (!userDevices.includes(fromDeviceStr)) {
				userDevices.push(fromDeviceStr)
			}

			// Filter out cached devices before database fetch
			const uncachedDevices = userDevices.filter(device => {
				const deviceKey = `${user}.${device}`
				return !migratedSessionCache.has(deviceKey)
			})

			// Bulk check session existence only for uncached devices
			const deviceSessionKeys = uncachedDevices.map(device => `${user}.${device}`)
			const existingSessions = await parsedKeys.get('session', deviceSessionKeys)

			// Step 3: Convert existing sessions to JIDs (only migrate sessions that exist)
			const deviceJids: string[] = []
			for (const [sessionKey, sessionData] of Object.entries(existingSessions)) {
				if (sessionData) {
					// Session exists in storage
					const deviceStr = sessionKey.split('.')[1]
					if (!deviceStr) continue
					const deviceNum = parseInt(deviceStr)
					let jid = deviceNum === 0 ? `${user}@s.whatsapp.net` : `${user}:${deviceNum}@s.whatsapp.net`
					if (deviceNum === 99) {
						jid = `${user}:99@hosted`
					}

					deviceJids.push(jid)
				}
			}

			logger.debug(
				{
					fromJid,
					totalDevices: userDevices.length,
					devicesWithSessions: deviceJids.length,
					devices: deviceJids
				},
				'bulk device migration complete - all user devices processed'
			)

			// Single transaction for all migrations
			return parsedKeys.transaction(
				async (): Promise<{ migrated: number; skipped: number; total: number }> => {
					// Prepare migration operations with addressing metadata
					type MigrationOp = {
						fromJid: string
						toJid: string
						pnUser: string
						lidUser: string
						deviceId: number
						fromAddr: libsignal.ProtocolAddress
						toAddr: libsignal.ProtocolAddress
					}

					const migrationOps: MigrationOp[] = deviceJids.map(jid => {
						const lidWithDevice = transferDevice(jid, toJid)
						const fromDecoded = jidDecode(jid)!
						const toDecoded = jidDecode(lidWithDevice)!

						return {
							fromJid: jid,
							toJid: lidWithDevice,
							pnUser: fromDecoded.user,
							lidUser: toDecoded.user,
							deviceId: fromDecoded.device || 0,
							fromAddr: jidToSignalProtocolAddress(jid),
							toAddr: jidToSignalProtocolAddress(lidWithDevice)
						}
					})

					const totalOps = migrationOps.length
					let migratedCount = 0

					// Bulk fetch PN sessions - already exist (verified during device discovery)
					const pnAddrStrings = Array.from(new Set(migrationOps.map(op => op.fromAddr.toString())))
					const pnSessions = await parsedKeys.get('session', pnAddrStrings)

					// Prepare bulk session updates (PN → LID migration + deletion)
					const sessionUpdates: { [key: string]: Uint8Array | null } = {}

					for (const op of migrationOps) {
						const pnAddrStr = op.fromAddr.toString()
						const lidAddrStr = op.toAddr.toString()

						const pnSession = pnSessions[pnAddrStr]
						if (pnSession) {
							// Session exists (guaranteed from device discovery)
							const fromSession = libsignal.SessionRecord.deserialize(pnSession)
							if (fromSession.haveOpenSession()) {
								// Queue for bulk update: copy to LID, delete from PN
								sessionUpdates[lidAddrStr] = fromSession.serialize()
								sessionUpdates[pnAddrStr] = null

								migratedCount++
							}
						}
					}

					// Single bulk session update for all migrations
					if (Object.keys(sessionUpdates).length > 0) {
						await parsedKeys.set({ session: sessionUpdates })
						logger.debug({ migratedSessions: migratedCount }, 'bulk session migration complete')

						// Cache device-level migrations
						for (const op of migrationOps) {
							if (sessionUpdates[op.toAddr.toString()]) {
								const deviceKey = `${op.pnUser}.${op.deviceId}`
								migratedSessionCache.set(deviceKey, true)
							}
						}
					}

					const skippedCount = totalOps - migratedCount
					return { migrated: migratedCount, skipped: skippedCount, total: totalOps }
				},
				`migrate-${deviceJids.length}-sessions-${jidDecode(toJid)?.user}`
			)
		}
	}

	return repository
}

const jidToSignalProtocolAddress = (jid: string): libsignal.ProtocolAddress => {
	const decoded = jidDecode(jid)!
	const { user, device, server, domainType } = decoded

	if (!user) {
		throw new Error(
			`JID decoded but user is empty: "${jid}" -> user: "${user}", server: "${server}", device: ${device}`
		)
	}

	const signalUser = domainType !== WAJIDDomains.WHATSAPP ? `${user}_${domainType}` : user
	const finalDevice = device || 0

	if (device === 99 && decoded.server !== 'hosted' && decoded.server !== 'hosted.lid') {
		throw new Error('Unexpected non-hosted device JID with device 99. This ID seems invalid. ID:' + jid)
	}

	return new libsignal.ProtocolAddress(signalUser, finalDevice)
}

const jidToSignalSenderKeyName = (group: string, user: string): SenderKeyName => {
	return new SenderKeyName(group, jidToSignalProtocolAddress(user))
}

/**
 * Cria o storage do Signal Protocol com tratamento robusto de erros
 */
function signalStorage(
	{ creds, keys }: SignalAuthState,
	lidMapping: LIDMappingStore
): SenderKeyStore & libsignal.SignalStorage {
	// Resolver endereço PN para LID se existir mapeamento
	const resolveLIDSignalAddress = async (id: string): Promise<string> => {
		try {
			if (id.includes('.')) {
				const [deviceId, device] = id.split('.')
				const [user, domainType_] = deviceId!.split('_')
				const domainType = parseInt(domainType_ || '0')

				// Se já é LID, retornar diretamente
				if (domainType === WAJIDDomains.LID || domainType === WAJIDDomains.HOSTED_LID) return id

				// Tentar converter PN para LID
				const pnJid = `${user!}${device !== '0' ? `:${device}` : ''}@${domainType === WAJIDDomains.HOSTED ? 'hosted' : 's.whatsapp.net'}`
				const lidForPN = await lidMapping.getLIDForPN(pnJid)
				if (lidForPN) {
					const lidAddr = jidToSignalProtocolAddress(lidForPN)
					return lidAddr.toString()
				}
			}
		} catch (error) {
			// Silenciosamente ignorar erros e usar ID original
		}
		return id
	}

	return {
		/**
		 * Carrega sessão com tratamento de erros
		 */
		loadSession: async (id: string) => {
			try {
				const wireJid = await resolveLIDSignalAddress(id)
				const { [wireJid]: sess } = await keys.get('session', [wireJid])

				if (sess) {
					try {
						return libsignal.SessionRecord.deserialize(sess)
					} catch (deserializeError) {
						// Remover sessão corrompida silenciosamente
						await keys.set({ session: { [wireJid]: null } })
						return null
					}
				}
			} catch (e) {
				return null
			}

			return null
		},

		/**
		 * Armazena sessão - SEMPRE salvar, mesmo com serialize() retornando 0 bytes
		 */
		storeSession: async (id: string, session: libsignal.SessionRecord) => {
			try {
				const wireJid = await resolveLIDSignalAddress(id)
				if (session && typeof session.serialize === 'function') {
					const serialized = session.serialize()
					await keys.set({ session: { [wireJid]: serialized } })
				}
			} catch (error) {
				console.error('[storeSession] Erro:', (error as Error).message)
				throw error
			}
		},

		isTrustedIdentity: () => {
			return true // todo: implement
		},

		/**
		 * Carrega pre-key com validação robusta de formatos
		 */
		loadPreKey: async (id: number | string) => {
			try {
				const keyId = id.toString()
				const { [keyId]: key } = await keys.get('pre-key', [keyId])
				
				if (!key) return undefined
				
				// Validar estrutura da chave
				const privData = key.private || (key as any).privKey
				const pubData = key.public || (key as any).pubKey
				
				if (!privData || !pubData) return undefined
				
				// Converter para Buffer de forma segura
				const privKey = Buffer.isBuffer(privData) ? privData : Buffer.from(privData)
				const pubKey = Buffer.isBuffer(pubData) ? pubData : Buffer.from(pubData)
				
				// Validar tamanho mínimo das chaves (32 bytes para Curve25519)
				if (privKey.length < 32 || pubKey.length < 32) {
					await keys.set({ 'pre-key': { [keyId]: null } }) // Remover corrompida
					return undefined
				}
				
				return { privKey, pubKey }
			} catch (error) {
				return undefined
			}
		},

		removePreKey: (id: number) => keys.set({ 'pre-key': { [id]: null } }),

		/**
		 * Carrega signed pre-key com validação
		 */
		loadSignedPreKey: () => {
			try {
				const key = creds.signedPreKey
				if (!key?.keyPair?.private || !key?.keyPair?.public) {
					throw new Error('Invalid signed pre-key structure')
				}
				return {
					privKey: Buffer.from(key.keyPair.private),
					pubKey: Buffer.from(key.keyPair.public)
				}
			} catch (error) {
				throw new Error('Failed to load signed pre-key: ' + (error as Error).message)
			}
		},

		/**
		 * Carrega sender key com tratamento robusto de formatos
		 */
		loadSenderKey: async (senderKeyName: SenderKeyName) => {
			try {
				const keyId = senderKeyName.toString()
				const { [keyId]: key } = await keys.get('sender-key', [keyId])

				if (key) {
					// Validar que key não é tipo primitivo inválido
					if (typeof key === 'number' || typeof key === 'boolean') {
						await keys.set({ 'sender-key': { [keyId]: null } })
						return new SenderKeyRecord()
					}

					try {
						// Tratar diferentes formatos de dados salvos
						let dataToDeserialize = key
						
						// Formato BufferJSON: { type: 'Buffer', data: [...] }
						if (typeof key === 'object' && 'type' in key && (key as any).type === 'Buffer' && 'data' in key) {
							const uint8 = new Uint8Array((key as any).data)
							const jsonStr = new TextDecoder().decode(uint8)
							dataToDeserialize = JSON.parse(jsonStr)
						} else if (key instanceof Uint8Array || Buffer.isBuffer(key)) {
							const jsonStr = new TextDecoder().decode(key)
							dataToDeserialize = JSON.parse(jsonStr)
						} else if (typeof key === 'string') {
							dataToDeserialize = JSON.parse(key)
						} else if (Array.isArray(key)) {
							dataToDeserialize = key
						}
						
						return SenderKeyRecord.deserialize(dataToDeserialize)
					} catch (deserializeError) {
						// Remover chave corrompida silenciosamente
						await keys.set({ 'sender-key': { [keyId]: null } })
						return new SenderKeyRecord()
					}
				}
				return new SenderKeyRecord()
			} catch (error) {
				return new SenderKeyRecord()
			}
		},

		/**
		 * Armazena sender key - SEMPRE salvar (mesmo vazia, como o oficial)
		 */
		storeSenderKey: async (senderKeyName: SenderKeyName, key: SenderKeyRecord) => {
			try {
				const keyId = senderKeyName.toString()

				// Validar que key tem método serialize
				if (!key || typeof key.serialize !== 'function') {
					return
				}

				const serialized = key.serialize()
				// Converter para Uint8Array via JSON para persistência (mesmo formato do oficial)
				const jsonStr = JSON.stringify(serialized)
				const uint8 = new TextEncoder().encode(jsonStr)
				await keys.set({ 'sender-key': { [keyId]: uint8 } })
				
				// 🔐 BACKUP: Salvar no SQLite para sobreviver a restart
				// Isso é CRÍTICO para evitar "No session found" após reiniciar
				try {
					const backupStore = getKeyBackupStore()
					await backupStore.backupSenderKey(keyId, uint8)
					// Log removido - era muito spam (acontece a cada mensagem recebida)
					// O backup continua funcionando, apenas não loga mais
				} catch (e) {
					// Log de erro mantido para diagnóstico
					console.error(`❌ Failed to backup sender key: ${(e as Error).message}`)
				}
			} catch (error) {
				console.error('[storeSenderKey] Erro:', (error as Error).message)
				throw error
			}
		},

		getOurRegistrationId: () => creds.registrationId,

		getOurIdentity: () => {
			const { signedIdentityKey } = creds
			return {
				privKey: Buffer.from(signedIdentityKey.private),
				pubKey: Buffer.from(generateSignalPubKey(signedIdentityKey.public))
			}
		}
	}
}
